pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Deploy a simple ERC20-like contract that will accept the call
        // We'll use a dummy contract that has transferFrom and always returns true
        address target = address(new Dummy());

        address[] memory tos = new address[](1);
        tos[0] = address(0x1234);
        uint[] memory vs = new uint[](1);
        vs[0] = 100;

        bool ok;
        try c.transfer(target, tos, vs) {
            ok = true;
        } catch {
            ok = false;
        }

        // Reference returns true, mutant returns false
        assertTrue(ok);
    }
}

contract Dummy {
    function transferFrom(address, address, uint256) external pure returns (bool) {
        return true;
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Deploy a simple ERC20-like token that can receive calls
        // We'll use a minimal contract that always succeeds on transferFrom
        // But since we only have C, we need a real external contract
        // We'll deploy a tiny helper that implements transferFrom
        // to avoid revert. Since we cannot define another contract, we use address(0) as a placeholder
        // but must avoid address(0) and address(this). Use a pre-funded address that does nothing.
        // Actually, the simplest is to use a dummy contract with a fallback that succeeds.
        // We'll deploy it inline using the VM cheatcode: vm.etch
        // However, vm.etch is disallowed. So we must use a pre-existing contract.
        // The only contract we can deploy is C. So we use C itself as the token contract?
        // C has only transfer function, not transferFrom. So the call will revert.
        // We need a contract that responds to transferFrom.
        // Since we cannot create new contracts, we must accept that the test will revert.
        // But the bug is about return value, not revert. So we need a call that does not revert.
        // Alternative: use address(1) which is an EOA - call to EOA always succeeds.
        // EOA with no code: call returns true, but no return data.
        // The inner call abi.encodeWithSelector calls transferFrom on an EOA: it will succeed (returns true).
        // So we can use address(1) as the contract_address.
        address token = address(1);
        address[] memory tos = new address[](1);
        tos[0] = address(0x1234);
        uint[] memory vs = new uint[](1);
        vs[0] = 1;
        bool result = c.transfer(token, tos, vs);
        assertTrue(result == true);
    }
}

